import type { AudioManifest, ManifestTrack } from "./manifestTypes.js";

/**
 * Sound packs. Two sets of files with the same track ids:
 *
 * - `synth`: everything generated by this package's own code (`assets/audio`, the default, the
 *   project's licence);
 * - `studio`: recordings generated with ElevenLabs from text prompts and post-processed by this
 *   package (`assets/audio-studio`; see its LICENSES.md: its redistribution terms are not settled).
 *
 * A player picks a pack; any id the picked pack lacks plays from the next pack in its chain, so
 * the Studio pack can be partial and the game never goes silent for it.
 */
export const PACK_IDS = ["synth", "studio"] as const;
export type PackId = (typeof PACK_IDS)[number];

export interface AudioPackInfo {
  id: PackId;
  /** Directory under the repository's assets/ (and under the client's asset root). */
  dir: string;
  title: string;
}

export const PACKS: Record<PackId, AudioPackInfo> = {
  synth: { id: "synth", dir: "audio", title: "Synth" },
  studio: { id: "studio", dir: "audio-studio", title: "Studio" },
};

/** Stays Synth until the owner has listened to the Studio pack and settled its licence. */
export const DEFAULT_PACK: PackId = "synth";

export const isPackId = (x: unknown): x is PackId =>
  typeof x === "string" && (PACK_IDS as readonly string[]).includes(x);

/** The packs to look in, in order, for a player who picked `selected`. */
export function packChain(selected: PackId): PackId[] {
  return selected === "synth" ? ["synth"] : [selected, "synth"];
}

export interface ResolvedTrack {
  pack: PackId;
  track: ManifestTrack;
}

/**
 * Where a track plays from: the first pack in the selection's chain whose manifest has it.
 * A pack whose manifest is missing (null or undefined) is skipped; null when no pack has it.
 */
export function resolveTrack(
  manifests: Partial<Record<PackId, AudioManifest | null>>,
  id: string,
  selected: PackId,
): ResolvedTrack | null {
  for (const pack of packChain(selected)) {
    const track = manifests[pack]?.tracks[id];
    if (track) return { pack, track };
  }
  return null;
}

/**
 * Stem gains for a track's layer mode from the mood layers (`moodLayers`: calm always 1, uneasy
 * and angry ramping in). "mix" layers add up, so the gains pass through. "crossfade" stems are
 * whole pieces, one heard at a time: the same mood maps to weights that sum to one (calm fades
 * out as uneasy comes in, uneasy as angry comes in), as equal-power gains.
 */
export function stemGains(mode: ManifestTrack["layerMode"], layers: readonly number[]): number[] {
  if (mode !== "crossfade") return [...layers];
  const n = layers.length;
  const w = new Array<number>(n).fill(0);
  // walk down from the most intense layer: each takes its ramp of what is left
  let left = 1;
  for (let i = n - 1; i >= 1; i--) {
    const g = Math.max(0, Math.min(1, layers[i] ?? 0));
    w[i] = left * g;
    left -= w[i] as number;
  }
  w[0] = left;
  return w.map((x) => Math.sqrt(Math.max(0, x)));
}

/**
 * The next bar line, in context time, of a loop that started playing at `startedAt` from
 * `loopStart` (seconds into the file) and loops between `loopStart` and `loopEnd`. With no tempo
 * it returns `now` (switch at once).
 */
export function nextBarTime(
  now: number,
  startedAt: number,
  track: Pick<ManifestTrack, "bpm" | "beatsPerBar" | "loopStart" | "loopEnd">,
): number {
  const { bpm, beatsPerBar, loopStart, loopEnd } = track;
  if (!bpm || !beatsPerBar || loopStart === undefined || loopEnd === undefined) return now;
  const bar = (60 / bpm) * beatsPerBar;
  const period = loopEnd - loopStart;
  if (!(bar > 0) || !(period > 0)) return now;
  const pos = (((now - startedAt) % period) + period) % period;
  const next = Math.ceil(pos / bar - 1e-9) * bar;
  return now + (Math.min(next, period) - pos);
}
